<script>
  import ErrorNotice from './ErrorNotice.svelte';
 import {onMount} from 'svelte';
 import {api,json} from '../lib/api.js';
 import {bytes,time} from '../lib/format.js';
 import Icon from './Icon.svelte';
 import Dialog from './Dialog.svelte';
 import TaskMonitor from './TaskMonitor.svelte';
 let {readOnly=false}=$props();
 let data=$state(null),roots=$state([]),loading=$state(true),error=$state(''),message=$state(''),pending=$state(false),modal=$state(''),draft=$state(null),password=$state(''),repeat=$state(''),job=$state(''),restoring=$state(null),toRoot=$state(''),to=$state('');
 let source=$state(''),relative=$state('.'),mode=$state('direct'),limit=$state(10000),maxBytes=$state(8*1024**3),maxRuntime=$state('30m');
 $effect(()=>{if(source==='@photo-vault'){mode='encrypted';relative='.';}});
 let controller,disposed=false;
 const blocked=$derived(readOnly||pending||data?.busy);
 async function load(){controller?.abort();controller=new AbortController();loading=true;try{const [settings,storage]=await Promise.all([api('/api/v1/backup/webdav',{signal:controller.signal}),api('/api/v1/files/roots',{signal:controller.signal})]);if(disposed)return;data=settings;roots=storage.roots||[];source ||= roots.find(r=>r.available)?.id||'';limit=Math.min(limit,storage.limits?.copy_max_entries||10000);maxBytes=Math.min(maxBytes,storage.limits?.copy_max_bytes||8*1024**3);error='';}catch(e){if(!disposed&&e.name!=='AbortError')error=e.message;}finally{if(!disposed)loading=false;}}
 function connection(){draft={...data.connection,password:'',password_action:'keep'};modal='connection';error='';}
 async function saveConnection(event){event.preventDefault();if(blocked)return;pending=true;error='';try{data=await api('/api/v1/backup/webdav',json('PUT',{url:draft.url,username:draft.username,password:draft.password,password_action:draft.password?'replace':draft.password_action,allow_http:draft.allow_http,revision:draft.revision},{headers:{'X-Nasctl-Confirm':'1'}}));draft.password='';modal='';message='WebDAV 已保存，可以测试连接或开始备份。';}catch(e){error=e.message;}finally{pending=false;}}
 async function probe(){if(blocked)return;pending=true;error='';message='';try{await api('/api/v1/backup/webdav/probe',json('POST',{revision:data.connection.revision},{headers:{'X-Nasctl-Confirm':'1'}}));message='连接成功，可以读取这个 WebDAV 文件夹。';}catch(e){error=e.message;}finally{pending=false;}}
 async function run(event){event.preventDefault();if(blocked)return;if(mode==='encrypted'&&password!==repeat){error='两次输入的备份密码不一致';return;}pending=true;error='';message='';try{const result=await api('/api/v1/backup/webdav/run',json('POST',{root:source,path:relative,mode,limit,max_bytes:maxBytes,max_runtime:maxRuntime,password:mode==='encrypted'?password:'',revision:data.connection.revision},{headers:{'X-Nasctl-Confirm':'1'}}));job=result.job_id;password='';repeat='';await load();}catch(e){error=e.message;}finally{pending=false;}}
 async function retry(record){pending=true;error='';try{const result=await api('/api/v1/backup/webdav/retry',json('POST',{id:record.id},{headers:{'X-Nasctl-Confirm':'1'}}));job=result.job_id;await load();}catch(e){error=e.message;}finally{pending=false;}}
 function restore(record){restoring=record;toRoot=roots.find(r=>r.available&&r.writable)?.id||'';to='恢复-'+new Date().toISOString().slice(0,10)+'-'+record.id.slice(0,6);password='';modal='restore';error='';}
 async function submitRestore(event){event.preventDefault();if(blocked)return;pending=true;error='';try{const result=await api('/api/v1/backup/webdav/restore',json('POST',{id:restoring.id,to_root:toRoot,to,password:restoring.source.mode==='encrypted'?password:''},{headers:{'X-Nasctl-Confirm':'1'}}));job=result.job_id;password='';modal='';await load();}catch(e){error=e.message;}finally{pending=false;}}
 function close(){if(!pending){modal='';password='';repeat='';if(draft)draft.password='';}}
 onMount(()=>{load();return()=>{disposed=true;controller?.abort();password='';repeat='';};});
</script>
<div class="cloud-backup">
 {#if error}<ErrorNotice message={error}/>{/if}{#if message}<p class="notice success" role="status">{message}</p>{/if}
 {#if job}<section class="panel task-panel"><TaskMonitor id={job} onsettled={load}/></section>{/if}
 {#if loading&&!data}<p class="loading-state" role="status">正在读取备份空间…</p>{:else if data}
 {#if !data.connection.url}<section class="cloud-welcome"><span class="cloud-welcome-icon"><Icon name="cloud" size={38}/></span><h2>给文件多一个去处</h2><p>连接你的 WebDAV。普通文件原样保存，私密内容打成带密码的压缩包。</p><button class="button primary" disabled={blocked} onclick={connection}>连接 WebDAV</button></section>
 {:else}
 <section class="cloud-destination"><span class="cloud-destination-icon"><Icon name="cloud" size={25}/></span><div><strong>我的 WebDAV</strong><p>{data.connection.url}</p></div><div class="button-group"><button class="text-button" disabled={blocked} onclick={probe}>测试连接</button><button class="icon-button" aria-label="WebDAV 连接设置" disabled={blocked} onclick={connection}><Icon name="settings" size={19}/></button></div></section>
 <form class="cloud-compose panel" onsubmit={run}><div class="panel-heading"><div><h2>备份什么？</h2><p class="muted">选一个文件或文件夹，原文件会保留在 NAS 上。</p></div></div><div class="cloud-source"><label>存储位置<select aria-label="WebDAV 备份源" bind:value={source} required disabled={blocked}>{#if data.vault_available}<option value="@photo-vault">照片保险箱（加密数据）</option>{/if}{#each roots as root}<option value={root.id} disabled={!root.available}>{root.label||root.id}</option>{/each}</select></label><label>文件或文件夹<input aria-label="WebDAV 备份路径" bind:value={relative} required maxlength="1024" placeholder="照片/旅行（. 表示全部）" disabled={blocked||source==='@photo-vault'}/></label></div>
 {#if source==='@photo-vault'}<p class="field-help">备份保险箱的加密数据，不解密照片。恢复后仍需原保险箱密码。</p>{/if}<fieldset class="cloud-modes" disabled={blocked}><legend>备份方式</legend><label class:chosen={mode==='direct'}><input type="radio" name="backup-mode" value="direct" bind:group={mode} disabled={source==='@photo-vault'}/><Icon name="folder" size={23}/><strong>直接上传</strong><span>保留文件和目录结构，不打包、不加密。</span></label><label class:chosen={mode==='encrypted'}><input type="radio" name="backup-mode" value="encrypted" bind:group={mode}/><Icon name="lock" size={23}/><strong>加密压缩包</strong><span>先用 zstd 压缩，再用独立密码加密内容和内部文件名。</span></label></fieldset>
 {#if mode==='encrypted'}<div class="cloud-passwords"><label>备份密码<input type="password" aria-label="WebDAV 备份密码" bind:value={password} minlength="12" maxlength="256" required autocomplete="new-password" disabled={blocked}/></label><label>再次输入密码<input type="password" aria-label="确认 WebDAV 备份密码" bind:value={repeat} minlength="12" maxlength="256" required autocomplete="new-password" disabled={blocked}/></label><p class="field-help">至少 12 个字符。密码不会保存到 NAS；遗失后无法打开加密备份。</p></div>{/if}
 <details class="cloud-budgets"><summary>更多选项</summary><div class="form-grid"><label>条目上限<input aria-label="WebDAV 条目上限" type="number" min="2" max={data.limits.CopyMaxEntries} bind:value={limit} required/></label><label>原文件字节上限<input aria-label="WebDAV 字节上限" type="number" min="1" max={data.limits.CopyMaxBytes} bind:value={maxBytes} required/></label><label>最长运行时间<select bind:value={maxRuntime}><option value="10m">10 分钟</option><option value="30m">30 分钟</option><option value="2h">2 小时</option></select></label></div><p class="field-help">包含隐藏文件，跳过符号链接与系统保留目录。加密备份需要 NAS 状态盘暂存加密包。</p></details><footer class="cloud-compose-footer"><span>回读校验后才标记完成 · 原文件保留</span><button class="button primary" type="submit" disabled={blocked||!source||mode==='encrypted'&&password!==repeat}><Icon name="upload" size={17}/>{pending?'正在提交…':'开始备份'}</button></footer></form>
 {/if}
 <section class="cloud-history"><div class="section-heading"><h2>我的备份</h2><button class="icon-button" aria-label="刷新 WebDAV 备份" disabled={loading} onclick={load}><Icon name="refresh" size={18}/></button></div>{#if !data.records.length}<div class="cloud-history-empty"><Icon name="backup" size={27}/><p>完成的备份会留在这里，随时恢复到新文件夹。</p></div>{/if}
 {#each data.records as record(record.id)}<article class="cloud-record"><span class="cloud-record-icon" class:private={record.source.mode==='encrypted'}><Icon name={record.source.mode==='encrypted'?'lock':'folder'} size={22}/></span><div><h3>{record.source.mode==='encrypted'?'私密备份':'文件备份'}<span class="badge" class:complete={record.state==='complete'}>{({complete:'已校验',running:'处理中',failed:'未完成',interrupted:'已中断'})[record.state]||record.state}</span></h3><p>{time(record.created_at)} · {record.entries} 项 · {bytes(record.bytes)}</p><small>{record.source.root==='@photo-vault'?'照片保险箱':roots.find(r=>r.id===record.source.root)?.label||record.source.root} / {record.source.path}</small>{#if record.error}<ErrorNotice message={record.error} inline/>{/if}</div><div class="button-group">{#if record.state==='complete'}<button class="button secondary small" disabled={blocked||!roots.some(r=>r.available&&r.writable)} onclick={()=>restore(record)}>恢复</button>{#if record.source.mode==='encrypted'}<a class="icon-button" aria-label="下载加密备份包" title="下载加密包" href={'/api/v1/backup/webdav/'+record.id+'/download'} download><Icon name="download" size={18}/></a>{/if}{:else if record.retryable}<button class="button secondary small" disabled={blocked} onclick={()=>retry(record)}>重试上传</button>{/if}</div></article>{/each}</section>
 {/if}
</div>
{#if modal==='connection'}<Dialog title="连接 WebDAV" onclose={close}><form class="cloud-form" onsubmit={saveConnection}><label>WebDAV 文件夹地址<input aria-label="WebDAV 地址" bind:value={draft.url} required maxlength="2048" placeholder="https://cloud.example/dav/backups/"/></label><label>用户名<input aria-label="WebDAV 用户名" bind:value={draft.username} maxlength="256" autocomplete="username"/></label><label>密码或应用密码<input aria-label="WebDAV 登录密码" type="password" bind:value={draft.password} maxlength="4096" autocomplete="new-password" placeholder={draft.password_set?'已保存，留空保持原密码':''}/></label>{#if draft.password_set}<label class="check-row"><input type="checkbox" checked={draft.password_action==='clear'} onchange={e=>draft.password_action=e.currentTarget.checked?'clear':'keep'}/>清除已保存的登录密码</label>{/if}<label class="check-row"><input type="checkbox" bind:checked={draft.allow_http}/>允许 HTTP（仅可信局域网）</label><p class="field-help">使用已存在的文件夹。服务需支持 WebDAV 上传、读取和 MOVE；不会覆盖已有备份。</p>{#if error}<ErrorNotice message={error}/>{/if}<footer class="dialog-footer"><button class="button secondary" type="button" disabled={pending} onclick={close}>取消</button><button class="button primary" disabled={pending}>保存连接</button></footer></form></Dialog>
{:else if modal==='restore'}<Dialog title="恢复备份" onclose={close}><form class="cloud-form" onsubmit={submitRestore}><p>校验通过后保存到新文件夹，已有文件不会被覆盖。</p>{#if restoring.source.root==='@photo-vault'}<p class="notice">恢复的是保险箱加密数据，请停机后按恢复说明导入；照片仍需原保险箱密码解锁。</p>{/if}<label>存储位置<select aria-label="WebDAV 恢复存储位置" bind:value={toRoot} required>{#each roots.filter(r=>r.available&&r.writable) as root}<option value={root.id}>{root.label||root.id}</option>{/each}</select></label><label>新文件夹位置<input aria-label="WebDAV 恢复位置" bind:value={to} required maxlength="1024"/></label>{#if restoring.source.mode==='encrypted'}<label>备份密码<input aria-label="WebDAV 恢复密码" type="password" bind:value={password} required minlength="12" maxlength="256" autocomplete="off"/></label>{/if}{#if error}<ErrorNotice message={error}/>{/if}<footer class="dialog-footer"><button class="button secondary" type="button" disabled={pending} onclick={close}>取消</button><button class="button primary" disabled={pending||!toRoot}>校验并恢复</button></footer></form></Dialog>{/if}
